#nullable enable // autogenerated

using PVZEngine;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Definitions;
using MVZ2.GameContent.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.RandomSpider)]
    public class RandomSpider : AIEntityBehaviour
    {
        public RandomSpider(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            // 死亡后召唤蜘蛛种族（Spider_Exp，使用 <spider>/<smallSpider> 模板）的敌人
            HealthLossSpawnHelper.SpawnOnDeath(entity, info, SpawnWhitelist, SpawnWeights);
        }

        #region 可生成敌人加权池

        // 蜘蛛种族（mvz2:Spider_Exp）敌人列表，不含随机系列
        private static NamespaceID[] SpawnWhitelist = new NamespaceID[]
        {
            VanillaEnemyID.spider,
            VanillaEnemyID.caveSpider,
            VanillaEnemyID.motherTerror,
            VanillaEnemyID.parasiteTerror,
            VanillaEnemyID.PhaseSpider,
        };

        // 对应每种敌人的生成权重，数值越大越容易被抽中（默认 1，待细调）
        private static int[] SpawnWeights = new int[]
        {
            1, 1, 1, 1, 1,
        };

        #endregion
    }
}
